// Запросы в Travelpayouts: Актау -> Нячанг, вылет 15.10–30.11.2026.
// Стартуем ВСЕГДА из Актау (уточнено 29.09.2026). Алматы и Астана — не города вылета, а
// хабы: «Актау → Астана» отдельным билетом + «Астана → Нячанг».
//
// С 08.10.2026: только Нячанг и только два хаба — Алматы и Астана, причём во Вьетнам летим
// ПРЯМЫМ рейсом. Сквозные билеты из Актау не запрашиваем: в них 1–3 пересадки неизвестно где.
// Каждое плечо спрашиваем дважды — как есть и с direct=true: без этого дешёвый рейс
// с пересадкой на ту же дату прячет прямой, и он не попадает в выдачу вовсе.
//
// ВАЖНО про коды: TP отвечает ГОРОДСКИМИ кодами, не аэропортовыми. Проверено 18.08.2026:
// спрашиваешь CXR — приходит NHA. В списках держим то, что API ОТДАЁТ.
const MONTHS = ['2026-10', '2026-11', '2026-12'];  // окно 15.10–30.11; декабрь нужен второму плечу: стыковка до 72 ч
const ORIGIN = 'SCO';
const VN = ['NHA'];
const HUBS = ['ALA', 'NQZ'];

const out = [];
for (const m of MONTHS) for (const direct of ['false', 'true']) {
  // 1. первое плечо связки: Актау -> хаб
  for (const h of HUBS) out.push({ json: { origin: ORIGIN, destination: h, leg: 'legA', month: m, direct } });
  // 2. второе плечо связки: хаб -> Нячанг
  for (const h of HUBS) for (const d of VN) out.push({ json: { origin: h, destination: d, leg: 'legB', month: m, direct } });
}
return out;

// Архив цен Travelpayouts по сквозным маршрутам — «дёшево сейчас или нет».
// Медиану по связке из двух билетов никто не считает, сравнивать было бы не с чем.
// Эндпоинт один — /v2/prices/latest; /v1/prices/calendar не использовать: он отдаёт
// цены туда-обратно и игнорирует запрошенный месяц (проверено 17.08.2026).
const YEAR_START = '2026-01-01';
const ORIGINS = ['SCO'];
const VN = ['NHA'];

const out = [];
for (const origin of ORIGINS) for (const destination of VN) {
  out.push({ json: {
    key: `${origin}-${destination}`, kind: 'latest',
    url: 'https://api.travelpayouts.com/v2/prices/latest',
    qs: {
      origin, destination, currency: 'rub',
      period_type: 'year', beginning_of_period: YEAR_START,
      group_by: 'dates', one_way: 'true', sorting: 'price',
      page: '1', limit: '1000', show_to_affiliates: 'false',
    },
  } });
}
return out;

// ===== Актау -> Нячанг, вылет 15.10–30.11.2026 =====
// Стартуем всегда из Актау. На каждое направление считаем две вещи:
//   through — один билет, как продаёт рынок;
//   self    — два отдельных билета через хаб (Алматы и Астана тут тоже хабы).
// Цена везде ПОЛНАЯ от Актау, отдельной строки «подвоз» больше нет.
//
// ВАЖНО про коды: TP отвечает ГОРОДСКИМИ кодами (CXR->NHA, GYD->BAK, на DXB прилетает
// ещё и SHJ). В списках держим то, что API ОТДАЁТ, иначе фильтр съедает всю выдачу.
const SUF = ''; // '' для крона, ' Cmd' для ветки команды

const WINDOW = { min: '2026-10-15', max: '2026-11-30' };
const LEGB_MAX = '2026-12-03';   // WINDOW.max + 72 ч: самая длинная стыковка (Алматы)
const ORIGIN = 'SCO';
const VN = ['NHA'];               // только Нячанг: в Дананг прямых из Казахстана нет (решено 08.10.2026)
// Хабы — только Алматы и Астана, и плечо хаб -> Нячанг берём ТОЛЬКО прямым рейсом
// (решено 08.10.2026: связки через Урумчи/Бангкок с 2 пересадками во второй броне не нужны).
const HUBS = ['ALA', 'NQZ'];
const SHORT_MAX_H = 12;     // «короткая стыковка»: от минимума хаба (3 ч) до 12 ч, без ночёвки
const BOB_TOL = 500;        // 🏆: прямой + короткая стыковка не дороже лучшей цены больше чем на столько, ₽
const ASSUMED_LEG_H = 4;
const MIN_LAYOVER_H = 6;    // международная стыковка: багаж, паспортный контроль
const MAX_LAYOVER_H = 48;   // длинная пересадка допустима, двое суток — потолок
const OVERNIGHT_H = 12;     // дольше — нужна ночёвка, отель в стоимость
// Казахстанские хабы: из Актау прилетаем внутренним рейсом, так что 3 ч на перебор багажа
// хватает. В Алматы у пользователя есть где бесплатно пожить день-другой, поэтому там
// стыковка до 72 ч и ночёвка не считается минусом.
const LAYOVER = {
  ALA: { min: 3, max: 72, freeStay: true },
  NQZ: { min: 3, max: 48 },
};
const layover = h => ({ min: MIN_LAYOVER_H, max: MAX_LAYOVER_H, freeStay: false, ...(LAYOVER[h] || {}) });

// Коды, которые TP отдаёт не так, как мы спрашиваем.
const NORM = { CXR: 'NHA' };
const norm = c => NORM[c] || c;

const AIRLINES = {
  FZ: 'flydubai', EK: 'Emirates', TK: 'Turkish', VF: 'AJet', HY: 'Uzbekistan',
  KC: 'Air Astana', DV: 'SCAT', FS: 'FlyArystan', J2: 'AZAL', VJ: 'VietJet', VN: 'Vietnam Airlines',
  QH: 'Bamboo', CZ: 'China Southern', SU: 'Аэрофлот', U6: 'Уральские', QR: 'Qatar',
  G9: 'Air Arabia', IX: 'Air India Express', AI: 'Air India', GF: 'Gulf Air',
  PC: 'Pegasus', D7: 'AirAsia X', XJ: 'Thai AirAsia X', CA: 'Air China',
  MU: 'China Eastern', XY: 'flynas', KU: 'Kuwait Airways', WY: 'Oman Air',
  '6E': 'IndiGo', OD: 'Batik Air', ZE: 'Eastar Jet', IQ: 'Qazaq Air', TG: 'Thai Airways',
  MH: 'Malaysia Airlines', AK: 'AirAsia', SQ: 'Singapore', BI: 'Royal Brunei',
};
const CITY = {
  SCO: 'Актау', ALA: 'Алматы', NQZ: 'Астана', NHA: 'Нячанг', DAD: 'Дананг',
  SGN: 'Хошимин', HAN: 'Ханой', DXB: 'Дубай', SHJ: 'Шарджа', IST: 'Стамбул',
  TAS: 'Ташкент', BKK: 'Бангкок', KUL: 'Куала-Лумпур', URC: 'Урумчи',
};
const name = c => CITY[c] || c;
// винительный падеж — для фразы «через …», иначе получается «через Астана»
const VIA = { SCO: 'Актау', ALA: 'Алматы', NQZ: 'Астану', NHA: 'Нячанг', DAD: 'Дананг',
              SGN: 'Хошимин', HAN: 'Ханой', DXB: 'Дубай', SHJ: 'Шарджу', IST: 'Стамбул',
              TAS: 'Ташкент', BKK: 'Бангкок', KUL: 'Куала-Лумпур', URC: 'Урумчи' };
const via = c => VIA[c] || name(c);

const inDepart = d => Boolean(d && d >= WINDOW.min && d <= WINDOW.max);
const inLegB = d => Boolean(d && d >= WINDOW.min && d <= LEGB_MAX);
const hours = ms => ms / 3600000;

// --- 1. Разбор ответов Travelpayouts -----------------------------------------
// Держим всё, что попадает в расширенное окно; кто из офферов «первое плечо», а кто
// «второе», решаем при выборке.
const offers = [];
try {
  for (const item of $('Travelpayouts' + SUF).all()) {
    const r = item.json || {};
    if (r.success === false) continue;
    const rows = Array.isArray(r.data) ? r.data : (Array.isArray(r) ? r : []);

    for (const t of rows) {
      const depart_at = String(t.departure_at || t.depart_date || '');
      const date = depart_at.slice(0, 10);
      if (!inLegB(date)) continue;

      const price = Number(t.price != null ? t.price : t.value);
      if (!Number.isFinite(price) || price <= 0) continue;

      const transfers = Number(t.transfers != null ? t.transfers : t.number_of_changes);
      const dur = Number(t.duration_to || t.duration);

      offers.push({
        from: norm(t.origin), to: norm(t.destination), date, depart_at, price,
        airline_code: t.airline || null,
        airline: AIRLINES[t.airline] || t.airline || 'н/д',
        flight: t.flight_number != null ? String(t.flight_number) : null,
        transfers: Number.isFinite(transfers) ? transfers : null,
        duration_min: Number.isFinite(dur) && dur > 0 ? dur : null,
        src: 'tp',
        kind: transfers === 0 ? 'direct' : 'connect',
        in_depart: inDepart(date),
        link: t.link || null,
      });
    }
  }
} catch (e) {}

const cheapest = list => list.slice().sort((a, b) => a.price - b.price)[0] || null;
// Самый дешёвый на дату — отдельно среди прямых и среди рейсов с пересадкой: иначе дешёвый
// рейс с пересадкой прятал бы прямой на ту же дату, а категория «без пересадок» пустела.
const minByDate = (from, to, onlyDepartWindow, directOnly) => {
  const byDate = {};
  for (const o of offers) {
    if (o.from !== from || o.to !== to) continue;
    if (onlyDepartWindow && !o.in_depart) continue;
    if (directOnly && o.transfers !== 0) continue;
    const k = o.date + (o.transfers === 0 ? '|d' : '|c');
    if (!byDate[k] || o.price < byDate[k].price) byDate[k] = o;
  }
  return Object.values(byDate);
};
const arrivalOf = o => {
  const dep = new Date(o.depart_at);
  if (isNaN(dep)) return null;
  const mins = o.duration_min != null ? o.duration_min : ASSUMED_LEG_H * 60;
  return new Date(dep.getTime() + mins * 60000);
};

// --- 2. Связки через хаб ------------------------------------------------------
// Стыковку проверяем по времени вылета и прилёта, а не по датам: иначе получаются
// схемы, где второй рейс улетает раньше, чем приземлился первый.
const combos = [];
for (const hub of HUBS) {
  const legA = minByDate(ORIGIN, hub, true, false);
  if (!legA.length) continue;
  const L = layover(hub);
  for (const dst of VN) {
    const legB = minByDate(hub, dst, false, true);   // во Вьетнам — только прямым
    if (!legB.length) continue;
    for (const a of legA) {
      const arr = arrivalOf(a);
      if (!arr) continue;
      for (const b of legB) {
        const dep = new Date(b.depart_at);
        if (isNaN(dep)) continue;
        const gap = hours(dep - arr);
        if (gap < L.min || gap > L.max) continue;
        const overnight = gap > OVERNIGHT_H;
        combos.push({
          origin: ORIGIN, to: dst, hub, hub_city: name(hub), hub_via: via(hub),
          price: a.price + b.price, date: a.date,
          layover_h: Math.round(gap * 10) / 10,
          overnight, free_stay: overnight && L.freeStay,
          direct: a.transfers === 0,          // второе плечо прямое всегда, значит прямые оба
          short: gap <= SHORT_MAX_H,
          legA: a, legB: b, kind: 'self', src: 'tp',
          airline_code: a.airline_code,
          airline: `${a.airline} + ${b.airline}`,
        });
      }
    }
  }
}
// при равной цене выше тот, у кого стыковка короче — так выбор категории детерминирован
combos.sort((x, y) => (x.price - y.price) || (x.layover_h - y.layover_h));

// Категории по каждому хабу отдельно (сообщение про Астану и сообщение про Алматы):
//   best   — лучшая цена, любая стыковка в пределах хаба
//   direct — лучшая цена, где и Актау -> хаб прямой
//   short  — лучшая цена со стыковкой до SHORT_MAX_H
//   bob    — «всё сошлось»: прямой + короткая и при этом не дороже best больше чем на BOB_TOL
const cats = {};
for (const hub of HUBS) {
  const list = combos.filter(c => c.hub === hub);
  if (!list.length) { cats[hub] = null; continue; }
  const ideal = list.find(c => c.direct && c.short) || null;
  cats[hub] = {
    hub, hub_city: name(hub), hub_via: via(hub), count: list.length,
    best: list[0],
    direct: list.find(c => c.direct) || null,
    short: list.find(c => c.short) || null,
    bob: ideal && ideal.price <= list[0].price + BOB_TOL ? ideal : null,
  };
}

// Самый дешёвый перелёт Актау -> Алматы/Астана в окне. Нужен ветке живого мониторинга:
// tutu обходит «Алматы/Астана -> Вьетнам», и к той цене надо прибавлять первое плечо.
const kz_feed = {};
for (const h of ['ALA', 'NQZ']) {
  const f = cheapest(offers.filter(x => x.from === ORIGIN && x.to === h && x.in_depart));
  if (f) kz_feed[h] = { price: f.price, date: f.date, airline: f.airline };
}

// --- 3. Архив цен -------------------------------------------------------------
// Формат сверен с живым ответом: data — массив записей с value и depart_date,
// return_date пустой = one-way. Приоритет датам окна, иначе выборка шире.
const history = {}, historyWin = {};
const pushHist = (key, price, date) => {
  if (!Number.isFinite(price) || price <= 0) return;
  (history[key] = history[key] || []).push(price);
  if (inDepart(date)) (historyWin[key] = historyWin[key] || []).push(price);
};
try {
  for (const item of $('TP History' + SUF).all()) {
    const r = item.json || {};
    if (r.success === false) continue;
    const data = r.data;
    if (!Array.isArray(data)) continue;
    for (const t of data) {
      if (!t || !t.origin || !t.destination) continue;
      if (t.return_date) continue;
      pushHist(`${norm(t.origin)}-${norm(t.destination)}`,
               Number(t.value != null ? t.value : t.price),
               String(t.depart_date || '').slice(0, 10));
    }
  }
} catch (e) {}

const MIN_SAMPLE = 10;
const stats = {};
for (const key of Object.keys(history)) {
  const win = historyWin[key] || [];
  const useWin = win.length >= MIN_SAMPLE;
  const s = (useWin ? win : history[key]).slice().sort((a, b) => a - b);
  stats[key] = { min: s[0], median: s[Math.floor(s.length / 2)], count: s.length,
                 scope: useWin ? 'наши даты' : 'все даты' };
}

// --- 4. Сводка по направлениям ------------------------------------------------
const routes = {};
for (const dst of VN) {
  const key = `${ORIGIN}-${dst}`;
  const through = offers.filter(o => o.from === ORIGIN && o.to === dst && o.in_depart);
  const self = combos.filter(c => c.to === dst);
  if (!through.length && !self.length) continue;

  const byDate = {};
  for (const o of through) {
    if (!byDate[o.date] || o.price < byDate[o.date].price) byDate[o.date] = o;
  }
  // по одной лучшей связке на хаб: иначе топ забивают три даты одного и того же хаба
  // (self уже отсортирован по цене, так что первая встреченная — самая дешёвая)
  const perHub = {};
  for (const c of self) if (!perHub[c.hub]) perHub[c.hub] = c;
  // лучшая связка на каждую дату вылета из Актау — для доски /dates. Крону она не
  // нужна, а execution data раздувает каждые 5 минут, поэтому только в ветке команды.
  const selfByDate = {};
  if (SUF) for (const c of self) if (!selfByDate[c.date]) selfByDate[c.date] = c;

  routes[key] = {
    origin: ORIGIN, dst, label: `${name(ORIGIN)} → ${name(dst)}`,
    through: { best: cheapest(through), byDate: Object.values(byDate).sort((a, b) => (a.date < b.date ? -1 : 1)), count: through.length },
    self: { best: self[0] || null, top: Object.values(perHub).slice(0, 4), count: self.length,
            byDate: Object.values(selfByDate) },
  };
}

const all = [];
for (const [key, r] of Object.entries(routes)) {
  if (r.through.best) all.push({ ...r.through.best, key, label: r.label, mode: 'through' });
  if (r.self.best) all.push({ ...r.self.best, key, label: r.label, mode: 'self' });
}
all.sort((a, b) => a.price - b.price);

return [{ json: {
  window: WINDOW, legb_max: LEGB_MAX, origin: ORIGIN, hubs: HUBS,
  routes, cats, short_max_h: SHORT_MAX_H, best: all[0] || null, kz_feed, stats,
  count: offers.length, comboCount: combos.length,
} }];

// ===================== НАСТРОЙКИ =====================
const THRESHOLD = 26000;     // 🔥 метка: полная цена от Актау не выше этой суммы, ₽
const MIN_DROP_RUB = 500;    // падение считается падением, если оно не меньше этой суммы…
const MIN_DROP_PCT = 3;      // …и не меньше этого процента от прошлой присланной цены
const HOLD_RUNS = 12;        // всё, кроме падения, должно продержаться столько прогонов подряд (≈1 ч)
// Кому уходят сообщения. Первым — владелец: если отправка второму упадёт (заблокировал бота),
// свои сообщения владелец к этому моменту уже получил, а ошибка придёт ему же через On Error.
const CHAT_IDS = ['648226895', '893232025'];
// =====================================================
// Решает, ПРИСЫЛАТЬ ли сообщение по хабу (Астана и Алматы — отдельными сообщениями).
// Присылаем только при изменении:
//   • цена в любой категории упала на MIN_DROP_* от прошлой ПРИСЛАННОЙ — сразу;
//   • сменился вариант, цена выросла, категория появилась или пропала — если это
//     держится HOLD_RUNS прогонов подряд.
// Зачем выдержка: кэш Travelpayouts дрожит. За 1–8.10.2026 одна и та же связка на 31.10
// прыгала 19,5 ↔ 15,5 тыс. по нескольку раз в день и дёргалась на ±200 ₽ каждый прогон —
// старая логика «новый минимум» выслала про неё 83 алерта за неделю.
// Сам текст собирает Enrich Tutu — после живой проверки каждого плеча на tutu.

const agg = $('Aggregate').first().json;
const store = $getWorkflowStaticData('global');

// первое плечо Актау -> Алматы/Астана для ветки живого мониторинга (Live Check)
store.kzFeed = agg.kz_feed || {};
if (!store.cats) store.cats = {};

const CATS = ['bob', 'best', 'direct', 'short'];
const CAT_NAME = { bob: '🏆 Всё сошлось', best: '💰 Лучшая цена',
                   direct: '✈️ Без пересадок', short: '⚡ Короткая стыковка' };
const rub = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' ₽';
const sig = c => `${c.legA.depart_at}|${c.legA.airline_code}|${c.legB.depart_at}|${c.legB.airline_code}`;
const thr = p => Math.max(MIN_DROP_RUB, p * MIN_DROP_PCT / 100);

// geo_id тути — внутренние id, не IATA (снято через suggest tutu)
const TUTU_GEO = { SCO: 112, ALA: 117, NQZ: 128, NHA: 2161 };
// tutu не проверяет searchId/sessionId, но требует их уникальности; crypto в Code-ноде
// нет, поэтому собираем uuid-подобную строку сами.
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0;
  return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});
const tutuBody = (from, to, date) => JSON.stringify({
  passengers: { child: 0, infant: 0, full: 1 }, serviceClass: 'Y',
  routes: [{ departureCityId: from, arrivalCityId: to, departureDate: date }],
  searchId: uuid(), sessionId: uuid(), pageId: 'n8nflightwatch',
  userData: {}, source: 'offers',
  dynamicFilters: { optionFilters: [], rangeFilters: [], buttonFilters: [], shortcuts: [], switchFilters: [] },
  // limit обязателен: без него tutu отдаёт только первые 10 предложений «по рекомендации»,
  // и нужный рейс (а то и половина прямых) в ответ не попадает — проверено 08.10.2026
  offset: 0, limit: 100, isNewSearch: true,
});

const plan = [];   // хабы, по которым уходит сообщение: { hub, reasons[] }
for (const hub of (agg.hubs || [])) {
  const cur = (agg.cats || {})[hub] || {};
  const first = !store.cats[hub];
  const st = store.cats[hub] || (store.cats[hub] = { sent: {}, hold: {} });
  const reasons = [];

  for (const cat of CATS) {
    const c = cur[cat] || null;
    const s = st.sent[cat] || null;
    if (first) continue;
    let held = false;
    if (c && s && c.price <= s.price - thr(s.price)) {
      reasons.push(`📉 ${CAT_NAME[cat]}: ${rub(c.price)} (было ${rub(s.price)}, −${rub(s.price - c.price)})`);
    } else if (c && s && c.price >= s.price + thr(s.price)) {
      held = true;
      if ((st.hold[cat] || 0) + 1 >= HOLD_RUNS) reasons.push(`📈 ${CAT_NAME[cat]}: ${rub(c.price)} (было ${rub(s.price)})`);
    } else if (c && s && sig(c) !== s.sig) {
      held = true;
      if ((st.hold[cat] || 0) + 1 >= HOLD_RUNS) reasons.push(`🔁 ${CAT_NAME[cat]}: другой вариант, ${rub(c.price)} (было ${rub(s.price)})`);
    } else if (c && !s) {
      held = true;
      if ((st.hold[cat] || 0) + 1 >= HOLD_RUNS) reasons.push(`🆕 ${CAT_NAME[cat]}: появился вариант, ${rub(c.price)}`);
    } else if (!c && s) {
      held = true;
      if ((st.hold[cat] || 0) + 1 >= HOLD_RUNS) reasons.push(`❌ ${CAT_NAME[cat]}: варианта больше нет (было ${rub(s.price)})`);
    }
    st.hold[cat] = held ? (st.hold[cat] || 0) + 1 : 0;
  }
  // первый прогон после установки: присылаем как есть, если есть что показать
  if (first && CATS.some(cat => cur[cat])) reasons.push('🆕 Первый замер по новым правилам');

  // «всё сошлось» появилось в том же прогоне, что и другой повод, — выдержку не ждём, называем сразу
  if (reasons.length && !first && cur.bob && !st.sent.bob && !reasons.some(r => r.includes(CAT_NAME.bob))) {
    reasons.unshift(`${CAT_NAME.bob}: прямые рейсы, короткая стыковка и лучшая цена разом`);
  }
  if (first || reasons.length) {
    // сообщение показывает все категории сразу — значит, и точку отсчёта обновляем по всем
    st.sent = {};
    for (const cat of CATS) if (cur[cat]) st.sent[cat] = { sig: sig(cur[cat]), price: cur[cat].price };
    st.hold = {};
  }
  if (reasons.length) plan.push({ hub, reasons });
}

if (!plan.length) return [];

// По элементу на каждое уникальное плечо всех показываемых вариантов — их проверит tutu.
const out = [];
const seen = new Set();
const meta = { chat_ids: CHAT_IDS, threshold: THRESHOLD, plan };
for (const p of plan) {
  const cur = (agg.cats || {})[p.hub] || {};
  for (const cat of CATS) {
    const c = cur[cat];
    if (!c) continue;
    for (const l of [c.legA, c.legB]) {
      const key = `${l.from}-${l.to}:${l.date}`;
      if (seen.has(key) || !TUTU_GEO[l.from] || !TUTU_GEO[l.to]) continue;
      seen.add(key);
      out.push({ json: { ...meta, leg_key: key, body: tutuBody(TUTU_GEO[l.from], TUTU_GEO[l.to], l.date) } });
    }
  }
}
// у хаба пропали все варианты — проверять нечего, но пустой выход обрубил бы ветку
if (!out.length) {
  out.push({ json: { ...meta, leg_key: null, body: tutuBody(112, TUTU_GEO[plan[0].hub] || 128, agg.window.min) } });
}
return out;

// Дописывает к сообщению по хабу вердикт AirHint по плечу «хаб → Нячанг» лучшего варианта.
// Пары «сообщение ↔ ответ» сводим ПО ИНДЕКСУ: нода AirHint стоит с continueRegularOutput,
// поэтому на каждый входной элемент приходит ровно один выходной, даже если запрос упал.
// Если AirHint промолчал или отдал пустоту — уходит исходный текст, сообщение не теряем.
const rub = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' ₽';
const CITY = { ALA: 'Алматы', NQZ: 'Астана' };

const ahLine = (r, hub) => {
  try {
    if (!r || typeof r !== 'object' || r.error) return '';
    const pr = Array.isArray(r.price_range) && r.price_range.length >= 3 ? r.price_range : null;
    if (!r.suggestion && !pr) return '';
    const verdict = r.suggestion === 'Buy' ? 'брать'
      : r.suggestion === 'Wait' ? 'советует подождать, цена может упасть'
      : String(r.suggestion || 'без вердикта');
    let line = `\n🔮 AirHint, ${CITY[hub] || hub} → Нячанг: ${verdict}`;
    // price_range — вилка по МАРШРУТУ, а не по конкретной дате (проверено 27.08.2026:
    // на 20.10 и 28.10 ответ одинаковый). Так и подписываем.
    if (pr) line += `\n   по маршруту обычно ${rub(pr[0])} – ${rub(pr[1])}, типично ${rub(pr[2])}`;
    if (r.max_saving) line += `\n   потенциал экономии ~${r.max_saving}`;
    if (Number.isFinite(Number(r.confidence))) line += ` · confidence ${r.confidence}`;
    return line;
  } catch (e) { return ''; }
};

const msgs = $('Enrich Tutu').all();
const ready = [];
$input.all().forEach((item, i) => {
  const base = msgs[i] ? msgs[i].json : null;
  if (!base) return;
  // если в сообщении нет ни одного варианта — спрашивать AirHint было не о чем
  const full = base.text + (base.ah_price ? ahLine(item.json, base.hub) : '');
  // страховка от телеграмовского лимита в 4096 символов
  ready.push({ chat_ids: base.chat_ids || [], cb: base.cb,
               text: full.length > 3900 ? full.slice(0, 3890) + '…' : full });
});
// Каждое сообщение — каждому получателю. Сначала всё первому в списке (владельцу), потом
// остальным: Telegram Alert шлёт по порядку и на ошибке останавливается.
const out = [];
const chats = ready.length ? ready[0].chat_ids : [];
for (const chat_id of chats) for (const m of ready) out.push({ json: { chat_id, cb: m.cb, text: m.text } });
return out;

// Собирает сообщения по хабам — отдельно «через Астану» и «через Алматы» — из категорий
// Aggregate и ЖИВОЙ проверки каждого плеча на tutu (Tutu Verify). Пары «плечо ↔ ответ tutu»
// сводим по индексу с элементами Prepare.
// tutu даёт то, чего нет в кэше Travelpayouts: идёт ли рейс на самом деле, сколько он стоит
// сейчас, есть ли в тарифе багаж, почём тариф с багажом и сколько осталось мест.
// Категории считаются по цене БЕЗ багажа; багаж — справочной строкой под плечом.
const rub = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' ₽';
const MONTHS = ['янв', 'фев', 'мар', 'апр', 'мая', 'июн',
                'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];
const dm = iso => {
  const p = String(iso).slice(0, 10).split('-');
  return p.length === 3 ? `${Number(p[2])} ${MONTHS[Number(p[1]) - 1]}` : iso;
};
const hm = iso => String(iso || '').slice(11, 16);
const CITY = { SCO: 'Актау', ALA: 'Алматы', NQZ: 'Астана', NHA: 'Нячанг' };
const VIA = { ALA: 'Алматы', NQZ: 'Астану' };
const CATS = ['bob', 'best', 'direct', 'short'];

// Разбор ответа tutu: список предложений с сегментами и лесенкой тарифов.
const parseTutu = raw => {
  try {
    const arr = typeof raw === 'string' ? JSON.parse(raw) : raw;
    const d = Array.isArray(arr) ? arr[0] : arr;
    if (!d || !d.offers || !d.dictionary) return null;
    const common = d.dictionary.common || {}, avia = d.dictionary.avia || {};
    const segs = common.segments || {}, routes = common.routes || {};
    const fareApps = common.fareApplications || {};
    const conds = avia.conditions || {}, carriers = common.carriers || {};
    const val = x => (x && x.defined) ? Number(x.value) : null;
    const list = [];
    for (const o of Object.values(d.offers.actual || {})) {
      const rid = (o.routeIds || [])[0];
      const ids = ((routes[rid] || {}).segmentIds || [rid]).filter(id => segs[id]);
      if (!ids.length) continue;
      const legs = ids.map(id => {
        const s = segs[id];
        const car = (s.carriers || []).find(c => c.type === 'operating') || (s.carriers || [])[0];
        return { dep: s.departureDateTime || '', arr: s.arrivalDateTime || '',
                 num: s.voyageNumber || '', carrier: (car && carriers[car.id] && carriers[car.id].name) || 'н/д' };
      });
      const variants = [];
      for (const v of (o.offerVariants || [])) {
        const p = v.price && v.price.value;
        if (!p || !p.amount || !p.fraction) continue;
        // багаж варианта = худший по сегментам; kg/pc могут быть не заданы вовсе
        let kg = Infinity, pc = Infinity, seats = Infinity, known = false;
        for (const hashes of Object.values(v.fareApplications || {})) {
          for (const h of (hashes || [])) {
            const fa = fareApps[h];
            if (!fa) continue;
            if (Number.isFinite(Number(fa.seats))) seats = Math.min(seats, Number(fa.seats));
            const c = conds[fa.segmentConditions];
            if (!c) continue;
            const k = val(c.baggageKg), n = val(c.baggagePc);
            if (k == null && n == null) continue;
            known = true;
            kg = Math.min(kg, k == null ? 0 : k);
            pc = Math.min(pc, n == null ? 0 : n);
          }
        }
        variants.push({ price: p.amount / p.fraction, known,
                        bag: known && (kg > 0 || pc > 0), kg: Number.isFinite(kg) ? kg : 0,
                        seats: Number.isFinite(seats) ? seats : null });
      }
      if (!variants.length) continue;
      variants.sort((a, b) => a.price - b.price);
      list.push({ price: variants[0].price, legs, variants, direct: legs.length === 1 });
    }
    return list.sort((a, b) => a.price - b.price);
  } catch (e) { return null; }
};

// ответы tutu по ключу плеча
const live = {};
const prep = $('Prepare').all();
$input.all().forEach((item, i) => {
  const q = prep[i] ? prep[i].json : null;
  if (!q || !q.leg_key) return;
  const raw = item.json && (item.json.data != null ? item.json.data : item.json);
  live[q.leg_key] = parseTutu(raw);
});

const bagLine = o => {
  const v0 = o.variants[0];
  const seats = (v0.seats != null && v0.seats < 9) ? ` · мест осталось: ${v0.seats}` : '';
  if (!v0.known) return `багаж в тарифе не указан${seats}`;
  if (v0.bag) return `багаж${v0.kg ? ` ${v0.kg} кг` : ''} включён${seats}`;
  const vb = o.variants.find(v => v.bag);
  return (vb ? `без багажа · с багажом${vb.kg ? ` ${vb.kg} кг` : ''}: ${rub(vb.price)} (+${rub(vb.price - v0.price)})`
             : 'без багажа · докупка багажа — только у перевозчика') + seats;
};

// строка живой проверки под плечом
const liveLine = l => {
  const offers = live[`${l.from}-${l.to}:${l.date}`];
  if (offers == null) return '⚠️ tutu не ответил — цена только из кэша Aviasales';
  const same = offers.find(o => o.legs.length === (l.transfers || 0) + 1 &&
                                o.legs[0].dep.slice(0, 16) === String(l.depart_at).slice(0, 16));
  if (same) {
    const diff = same.price - l.price;
    const note = diff > l.price * 0.15 ? ` — дороже кэша на ${rub(diff)}, кэш мог протухнуть`
               : diff < -MIN_NOTE ? ` — дешевле кэша на ${rub(-diff)}` : '';
    const arr = same.legs[same.legs.length - 1].arr;
    return `✅ tutu сейчас ${rub(same.price)}${note} · прилёт ${hm(arr)}\n       ${bagLine(same)}`;
  }
  const other = offers.find(o => o.direct);
  if (other && l.transfers === 0) {
    return `⚠️ рейса в ${hm(l.depart_at)} tutu не видит. Прямой у него: ${rub(other.price)} · ` +
           `${other.legs[0].carrier} · ${hm(other.legs[0].dep)}\n       ${bagLine(other)}`;
  }
  return l.transfers === 0
    ? '⚠️ tutu прямого рейса на эту дату не видит — цена только из кэша Aviasales'
    : '⚠️ tutu этот вариант не видит — цена только из кэша Aviasales';
};
const MIN_NOTE = 300;   // расхождение с кэшем меньше этого — шум, не подписываем

const agg = $('Aggregate').first().json;
const meta = prep[0] ? prep[0].json : null;
if (!meta || !Array.isArray(meta.plan)) return [];
const CAT_NAME = { bob: '🏆 Всё сошлось', best: '💰 Лучшая цена',
                   direct: '✈️ Без пересадок', short: `⚡ Короткая стыковка (до ${agg.short_max_h} ч)` };
const stops = o => o.transfers === 0 ? 'прямой'
  : o.transfers > 0 ? `${o.transfers} пересадк${o.transfers === 1 ? 'а' : 'и'}` : '';
const legLine = (n, l) =>
  `  ${n}) ${CITY[l.from] || l.from} → ${CITY[l.to] || l.to} · ${rub(l.price)} · ${dm(l.date)} ${hm(l.depart_at)} · ` +
  `${l.airline}${stops(l) ? ` · ${stops(l)}` : ''}\n     ${liveLine(l)}`;
const sig = c => `${c.legA.depart_at}|${c.legA.airline_code}|${c.legB.depart_at}|${c.legB.airline_code}`;
// callback_data кнопки «🔄 Проверить цену» (лимит Telegram — 64 байта), разбирает Recheck Queries:
//   rc:<FROM>-<TO>-<ГГММДД>:<FROM>-<TO>-<ГГММДД>:<цена>
const cbLeg = l => `${l.from}-${l.to}-${String(l.date).slice(2).replace(/-/g, '')}`;

const out = [];
for (const p of meta.plan) {
  const cur = (agg.cats || {})[p.hub] || {};
  let text = `<b>✈️ Актау → ${CITY[p.hub]} → Нячанг</b>\n${p.reasons.join('\n')}\n`;

  // один и тот же вариант часто побеждает сразу в нескольких категориях — показываем его
  // одним блоком со всеми ярлыками, а не три раза подряд
  const blocks = [];
  for (const cat of CATS) {
    const c = cur[cat];
    if (!c) continue;
    const b = blocks.find(x => sig(x.c) === sig(c));
    if (b) b.cats.push(cat); else blocks.push({ c, cats: [cat] });
  }
  for (const b of blocks) {
    const c = b.c;
    text += `\n<b>${b.cats.map(x => CAT_NAME[x]).join(' · ')}</b>\n` +
      `<b>${rub(c.price)}</b>${c.price <= meta.threshold ? ' 🔥' : ''} · вылет из Актау ${dm(c.legA.date)}\n` +
      `${legLine(1, c.legA)}\n${legLine(2, c.legB)}\n` +
      `  стыковка ${c.layover_h} ч` +
      (c.free_stay ? ' 🏠 — ночуем у своих' : c.overnight ? ' 🛌 — нужна ночёвка' : '') + `\n`;
  }
  const missing = CATS.filter(cat => cat !== 'bob' && !cur[cat]).map(cat => CAT_NAME[cat]);
  if (!blocks.length) text += `\nСейчас связок с прямым рейсом в Нячанг через ${VIA[p.hub]} нет.\n`;
  else if (missing.length) text += `\nНет вариантов: ${missing.join(', ')}.\n`;
  if (blocks.length) {
    text += `\nЦены плеч — кэш Aviasales, без багажа; строки ✅/⚠️ — живой поиск tutu (у него агентская наценка).` +
            `\nБрони отдельные: багаж получать и сдавать заново, опоздание на второй рейс никто не компенсирует.`;
  }

  const top = blocks.length ? blocks[0].c : null;
  out.push({ json: {
    chat_ids: meta.chat_ids,
    text: text.length > 3900 ? text.slice(0, 3890) + '…' : text,
    cb: top ? `rc:${cbLeg(top.legA)}:${cbLeg(top.legB)}:${Math.round(top.price)}` : 'rc:0',
    // ah_* уезжают в AirHint: вердикт по плечу хаб → Нячанг лучшего варианта
    hub: p.hub,
    ah_airline: (top && top.legB.airline_code) || 'XX',
    ah_origin: p.hub, ah_dst: 'NHA',
    ah_date: top ? top.legB.date : agg.window.min,
    ah_price: top ? Math.round(top.legB.price) : 0,
  } });
}
return out;

// ===== Живой мониторинг через поиск tutu =====
// Зачем: Travelpayouts отдаёт КЭШ (ловили расхождение в 21 час), а tutu ходит в реальном
// времени и видит в том числе VietJet — костяк маршрута во Вьетнам. Проверено 27.08.2026:
// ALA→HAN прямым VietJet есть 18, 21, 25 и 28 октября (25 885 – 36 162 ₽), в остальные
// даты минимум даёт China Southern / China Eastern за 31–44 тыс.
// Маршруты из Алматы/Астаны — это второе плечо от Актау; первое плечо Live Check
// дописывает к алерту из кэша (store.kzFeed, его пишет Prepare).
//
// Обходим окно ПО КРУГУ, а не целиком: полный обход = 100 запросов, а крон каждые 5 минут.
// Берём SLOTS_PER_RUN штук за прогон, курсор храним в staticData — полный круг ~65 минут,
// нагрузка на tutu ~96 запросов в час. Круг короткий намеренно: сбросы за 0–3 дня до вылета
// жили в кэше считаные часы (разбор истории 1–8.10.2026).
const ROUTES = [
  // с 08.10.2026 — только второе плечо и только прямым: Дананг, Ханой и сквозные из Актау убраны
  { key: 'ALA-NHA', from: 117, to: 2161, label: 'Алматы → Нячанг' },
  { key: 'NQZ-NHA', from: 128, to: 2161, label: 'Астана → Нячанг' },
];
const WINDOW = { min: '2026-10-15', max: '2026-12-03' };  // вылеты второго плеча: окно из Актау + стыковка до 72 ч
const SLOTS_PER_RUN = 8;  // 2 маршрута × 50 дат = 100 слотов, круг ~65 минут

const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0;
  return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});
const body = (from, to, date) => JSON.stringify({
  passengers: { child: 0, infant: 0, full: 1 }, serviceClass: 'Y',
  routes: [{ departureCityId: from, arrivalCityId: to, departureDate: date }],
  searchId: uuid(), sessionId: uuid(), pageId: 'n8nflightwatch',
  userData: {}, source: 'offers',
  dynamicFilters: { optionFilters: [], rangeFilters: [], buttonFilters: [], shortcuts: [], switchFilters: [] },
  offset: 0, limit: 100, isNewSearch: true,   // без limit tutu отдаёт только первые 10 предложений
});

const dates = [];
const d = new Date(WINDOW.min + 'T00:00:00Z');
const end = new Date(WINDOW.max + 'T00:00:00Z');
while (d <= end) { dates.push(d.toISOString().slice(0, 10)); d.setUTCDate(d.getUTCDate() + 1); }

// плоский список слотов «маршрут × дата», порядок стабильный — курсор по нему и ходит
const slots = [];
for (const r of ROUTES) for (const date of dates) slots.push({ ...r, date });

const store = $getWorkflowStaticData('global');
let cursor = Number(store.liveCursor || 0);
if (!Number.isFinite(cursor) || cursor < 0 || cursor >= slots.length) cursor = 0;

const out = [];
for (let i = 0; i < SLOTS_PER_RUN; i++) {
  const s = slots[(cursor + i) % slots.length];
  out.push({ json: { key: s.key, label: s.label, date: s.date, body: body(s.from, s.to, s.date) } });
}
store.liveCursor = (cursor + SLOTS_PER_RUN) % slots.length;
return out;

// Сверяет живую выдачу tutu с тем, что видели в прошлый обход, и пингует при падении.
// Смысл ветки: Travelpayouts — кэш (ловили протухание на 21 час), tutu — реальное время.
// Поэтому здесь НЕ «покупай», а «беги проверяй»: у самого VietJet в EUR обычно дешевле,
// чем у tutu с агентской наценкой, а окончательную цену смотрим на Aviasales / у перевозчика.
const LIVE_THRESHOLD = 30000; // ₽, «дёшево само по себе» — пинг даже без падения
const DROP_PCT = 7;           // % падения от прошлого замера
const MIN_DROP_RUB = 500;     // ₽, меньшее удешевление — шум курса, не повод писать
// те же получатели, что в Prepare; первым — владелец (см. комментарий там)
const CHAT_IDS = ['648226895', '893232025'];

const MONTHS = ['янв', 'фев', 'мар', 'апр', 'мая', 'июн',
                'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];
const dm = iso => {
  const p = String(iso).split('-');
  return p.length === 3 ? `${Number(p[2])} ${MONTHS[Number(p[1]) - 1]}` : iso;
};
const rub = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' ₽';

const parseTutu = raw => {
  try {
    const arr = typeof raw === 'string' ? JSON.parse(raw) : raw;
    const d = Array.isArray(arr) ? arr[0] : arr;
    if (!d || !d.offers) return null;
    const carriers = {};
    for (const [k, v] of Object.entries(d.dictionary.common.carriers || {})) carriers[k] = v.name || v.code || k;
    const points = {};
    for (const [k, v] of Object.entries((d.dictionary.avia || {}).points || {})) points[k] = v.airportCode;
    const segs = d.dictionary.common.segments || {}, routes = d.dictionary.common.routes || {};
    let best = null;
    for (const o of Object.values((d.offers || {}).actual || {})) {
      const prices = (o.offerVariants || []).map(v => v.price && v.price.value)
        .filter(p => p && p.amount && p.fraction).map(p => p.amount / p.fraction);
      if (!prices.length) continue;
      const price = Math.min(...prices);
      const legs = [];
      for (const rid of (o.routeIds || [])) {
        const r = routes[rid] || {};
        for (const sid of (r.segmentIds || [rid])) {
          const s = segs[sid];
          if (!s) continue;
          const car = (s.carriers || []).find(c => c.type === 'marketing') || (s.carriers || [])[0];
          legs.push({ from: points[String(s.departureGeoPointId)] || '?',
                      to: points[String(s.arrivalGeoPointId)] || '?',
                      dep: s.departureDateTime || null,
                      carrier: (car && carriers[car.id]) || s.voyageNumber || 'н/д' });
        }
      }
      if (legs.length !== 1) continue;   // во Вьетнам — только прямым рейсом
      if (!best || price < best.price) {
        best = { price, transfers: Math.max(0, legs.length - 1),
                 carrier: legs.length ? legs[0].carrier : 'н/д',
                 dep: legs.length ? legs[0].dep : null,
                 path: legs.length ? [legs[0].from, ...legs.map(l => l.to)].join(' → ') : '' };
      }
    }
    return best;
  } catch (e) { return null; }
};

const store = $getWorkflowStaticData('global');
if (!store.live) store.live = {};

// Маршруты из Алматы/Астаны — только второе плечо: летим-то из Актау. Первое плечо берём
// из кэша TP, его кладёт в staticData нода Prepare.
const FEED_CITY = { ALA: 'Алматы', NQZ: 'Астану' };
const feedLine = key => {
  const from = String(key).split('-')[0];
  const f = (store.kzFeed || {})[from];
  if (!FEED_CITY[from]) return '';
  return f ? `\n+ Актау → ${FEED_CITY[from]} от ${rub(f.price)} (${dm(f.date)}, ${f.airline}, кэш) — стыковку сверь по датам`
           : `\n+ ещё перелёт Актау → ${FEED_CITY[from]}`;
};

const queries = $('Live Queries').all();
const out = [];

$input.all().forEach((item, i) => {
  const q = queries[i] ? queries[i].json : null;
  if (!q || !q.key) return;
  const raw = item.json && (item.json.data != null ? item.json.data : item.json);
  const best = parseTutu(raw);
  const slot = `${q.key}:${q.date}`;
  const prev = store.live[slot] || null;

  if (!best) { store.live[slot] = { price: null, seen: true }; return; }

  const price = Math.round(best.price);
  const wasPrice = prev && Number.isFinite(Number(prev.price)) ? Number(prev.price) : null;
  // первый замер только запоминаем: иначе при первом запуске улетит пачка сообщений
  const fresh = !prev;
  store.live[slot] = { price, carrier: best.carrier, transfers: best.transfers,
                       path: best.path, min: Math.min(price, (prev && prev.min) || price) };
  if (fresh || wasPrice == null) return;

  const dropped = price <= wasPrice * (1 - DROP_PCT / 100);
  const cheap = price <= LIVE_THRESHOLD && price <= wasPrice - MIN_DROP_RUB;
  if (!dropped && !cheap) return;

  const head = dropped ? '⚡ Живая цена упала' : '⚡ Живая цена ниже порога';
  const stops = best.transfers === 0 ? 'прямой' : `пересадок ${best.transfers}`;
  out.push({ json: { chat_id: null,
    cb: `rc:${q.key}-${String(q.date).slice(2).replace(/-/g, '')}:${price}`, text:
    `${head}\n${q.label}, ${dm(q.date)}\n` +
    `${rub(price)} (было ${rub(wasPrice)}, −${Math.round((1 - price / wasPrice) * 100)} %)\n` +
    `${best.carrier} · ${stops}${best.path ? ` · ${best.path}` : ''}` +
    (best.dep ? ` · вылет ${String(best.dep).slice(11, 16)}` : '') +
    feedLine(q.key) +
    `\n\nЭто ЖИВОЙ поиск tutu, не кэш. Беги проверять на Aviasales и на сайте перевозчика — ` +
    `у VietJet в евро обычно дешевле, чем у tutu с агентской наценкой.` }});
});

// каждый алерт — каждому получателю: сначала все первому в списке, потом остальным
return CHAT_IDS.flatMap(chat_id => out.map(m => ({ json: { ...m.json, chat_id } })));

// Запросы в Travelpayouts: Актау -> Нячанг, вылет 15.10–30.11.2026.
// Стартуем ВСЕГДА из Актау (уточнено 29.09.2026). Алматы и Астана — не города вылета, а
// хабы: «Актау → Астана» отдельным билетом + «Астана → Нячанг».
//
// С 08.10.2026: только Нячанг и только два хаба — Алматы и Астана, причём во Вьетнам летим
// ПРЯМЫМ рейсом. Сквозные билеты из Актау не запрашиваем: в них 1–3 пересадки неизвестно где.
// Каждое плечо спрашиваем дважды — как есть и с direct=true: без этого дешёвый рейс
// с пересадкой на ту же дату прячет прямой, и он не попадает в выдачу вовсе.
//
// ВАЖНО про коды: TP отвечает ГОРОДСКИМИ кодами, не аэропортовыми. Проверено 18.08.2026:
// спрашиваешь CXR — приходит NHA. В списках держим то, что API ОТДАЁТ.
const MONTHS = ['2026-10', '2026-11', '2026-12'];  // окно 15.10–30.11; декабрь нужен второму плечу: стыковка до 72 ч
const ORIGIN = 'SCO';
const VN = ['NHA'];
const HUBS = ['ALA', 'NQZ'];

const out = [];
for (const m of MONTHS) for (const direct of ['false', 'true']) {
  // 1. первое плечо связки: Актау -> хаб
  for (const h of HUBS) out.push({ json: { origin: ORIGIN, destination: h, leg: 'legA', month: m, direct } });
  // 2. второе плечо связки: хаб -> Нячанг
  for (const h of HUBS) for (const d of VN) out.push({ json: { origin: h, destination: d, leg: 'legB', month: m, direct } });
}
return out;

// Архив цен Travelpayouts по сквозным маршрутам — «дёшево сейчас или нет».
// Медиану по связке из двух билетов никто не считает, сравнивать было бы не с чем.
// Эндпоинт один — /v2/prices/latest; /v1/prices/calendar не использовать: он отдаёт
// цены туда-обратно и игнорирует запрошенный месяц (проверено 17.08.2026).
const YEAR_START = '2026-01-01';
const ORIGINS = ['SCO'];
const VN = ['NHA'];

const out = [];
for (const origin of ORIGINS) for (const destination of VN) {
  out.push({ json: {
    key: `${origin}-${destination}`, kind: 'latest',
    url: 'https://api.travelpayouts.com/v2/prices/latest',
    qs: {
      origin, destination, currency: 'rub',
      period_type: 'year', beginning_of_period: YEAR_START,
      group_by: 'dates', one_way: 'true', sorting: 'price',
      page: '1', limit: '1000', show_to_affiliates: 'false',
    },
  } });
}
return out;

// ===== Актау -> Нячанг, вылет 15.10–30.11.2026 =====
// Стартуем всегда из Актау. На каждое направление считаем две вещи:
//   through — один билет, как продаёт рынок;
//   self    — два отдельных билета через хаб (Алматы и Астана тут тоже хабы).
// Цена везде ПОЛНАЯ от Актау, отдельной строки «подвоз» больше нет.
//
// ВАЖНО про коды: TP отвечает ГОРОДСКИМИ кодами (CXR->NHA, GYD->BAK, на DXB прилетает
// ещё и SHJ). В списках держим то, что API ОТДАЁТ, иначе фильтр съедает всю выдачу.
const SUF = ' Cmd'; // '' для крона, ' Cmd' для ветки команды

const WINDOW = { min: '2026-10-15', max: '2026-11-30' };
const LEGB_MAX = '2026-12-03';   // WINDOW.max + 72 ч: самая длинная стыковка (Алматы)
const ORIGIN = 'SCO';
const VN = ['NHA'];               // только Нячанг: в Дананг прямых из Казахстана нет (решено 08.10.2026)
// Хабы — только Алматы и Астана, и плечо хаб -> Нячанг берём ТОЛЬКО прямым рейсом
// (решено 08.10.2026: связки через Урумчи/Бангкок с 2 пересадками во второй броне не нужны).
const HUBS = ['ALA', 'NQZ'];
const SHORT_MAX_H = 12;     // «короткая стыковка»: от минимума хаба (3 ч) до 12 ч, без ночёвки
const BOB_TOL = 500;        // 🏆: прямой + короткая стыковка не дороже лучшей цены больше чем на столько, ₽
const ASSUMED_LEG_H = 4;
const MIN_LAYOVER_H = 6;    // международная стыковка: багаж, паспортный контроль
const MAX_LAYOVER_H = 48;   // длинная пересадка допустима, двое суток — потолок
const OVERNIGHT_H = 12;     // дольше — нужна ночёвка, отель в стоимость
// Казахстанские хабы: из Актау прилетаем внутренним рейсом, так что 3 ч на перебор багажа
// хватает. В Алматы у пользователя есть где бесплатно пожить день-другой, поэтому там
// стыковка до 72 ч и ночёвка не считается минусом.
const LAYOVER = {
  ALA: { min: 3, max: 72, freeStay: true },
  NQZ: { min: 3, max: 48 },
};
const layover = h => ({ min: MIN_LAYOVER_H, max: MAX_LAYOVER_H, freeStay: false, ...(LAYOVER[h] || {}) });

// Коды, которые TP отдаёт не так, как мы спрашиваем.
const NORM = { CXR: 'NHA' };
const norm = c => NORM[c] || c;

const AIRLINES = {
  FZ: 'flydubai', EK: 'Emirates', TK: 'Turkish', VF: 'AJet', HY: 'Uzbekistan',
  KC: 'Air Astana', DV: 'SCAT', FS: 'FlyArystan', J2: 'AZAL', VJ: 'VietJet', VN: 'Vietnam Airlines',
  QH: 'Bamboo', CZ: 'China Southern', SU: 'Аэрофлот', U6: 'Уральские', QR: 'Qatar',
  G9: 'Air Arabia', IX: 'Air India Express', AI: 'Air India', GF: 'Gulf Air',
  PC: 'Pegasus', D7: 'AirAsia X', XJ: 'Thai AirAsia X', CA: 'Air China',
  MU: 'China Eastern', XY: 'flynas', KU: 'Kuwait Airways', WY: 'Oman Air',
  '6E': 'IndiGo', OD: 'Batik Air', ZE: 'Eastar Jet', IQ: 'Qazaq Air', TG: 'Thai Airways',
  MH: 'Malaysia Airlines', AK: 'AirAsia', SQ: 'Singapore', BI: 'Royal Brunei',
};
const CITY = {
  SCO: 'Актау', ALA: 'Алматы', NQZ: 'Астана', NHA: 'Нячанг', DAD: 'Дананг',
  SGN: 'Хошимин', HAN: 'Ханой', DXB: 'Дубай', SHJ: 'Шарджа', IST: 'Стамбул',
  TAS: 'Ташкент', BKK: 'Бангкок', KUL: 'Куала-Лумпур', URC: 'Урумчи',
};
const name = c => CITY[c] || c;
// винительный падеж — для фразы «через …», иначе получается «через Астана»
const VIA = { SCO: 'Актау', ALA: 'Алматы', NQZ: 'Астану', NHA: 'Нячанг', DAD: 'Дананг',
              SGN: 'Хошимин', HAN: 'Ханой', DXB: 'Дубай', SHJ: 'Шарджу', IST: 'Стамбул',
              TAS: 'Ташкент', BKK: 'Бангкок', KUL: 'Куала-Лумпур', URC: 'Урумчи' };
const via = c => VIA[c] || name(c);

const inDepart = d => Boolean(d && d >= WINDOW.min && d <= WINDOW.max);
const inLegB = d => Boolean(d && d >= WINDOW.min && d <= LEGB_MAX);
const hours = ms => ms / 3600000;

// --- 1. Разбор ответов Travelpayouts -----------------------------------------
// Держим всё, что попадает в расширенное окно; кто из офферов «первое плечо», а кто
// «второе», решаем при выборке.
const offers = [];
try {
  for (const item of $('Travelpayouts' + SUF).all()) {
    const r = item.json || {};
    if (r.success === false) continue;
    const rows = Array.isArray(r.data) ? r.data : (Array.isArray(r) ? r : []);

    for (const t of rows) {
      const depart_at = String(t.departure_at || t.depart_date || '');
      const date = depart_at.slice(0, 10);
      if (!inLegB(date)) continue;

      const price = Number(t.price != null ? t.price : t.value);
      if (!Number.isFinite(price) || price <= 0) continue;

      const transfers = Number(t.transfers != null ? t.transfers : t.number_of_changes);
      const dur = Number(t.duration_to || t.duration);

      offers.push({
        from: norm(t.origin), to: norm(t.destination), date, depart_at, price,
        airline_code: t.airline || null,
        airline: AIRLINES[t.airline] || t.airline || 'н/д',
        flight: t.flight_number != null ? String(t.flight_number) : null,
        transfers: Number.isFinite(transfers) ? transfers : null,
        duration_min: Number.isFinite(dur) && dur > 0 ? dur : null,
        src: 'tp',
        kind: transfers === 0 ? 'direct' : 'connect',
        in_depart: inDepart(date),
        link: t.link || null,
      });
    }
  }
} catch (e) {}

const cheapest = list => list.slice().sort((a, b) => a.price - b.price)[0] || null;
// Самый дешёвый на дату — отдельно среди прямых и среди рейсов с пересадкой: иначе дешёвый
// рейс с пересадкой прятал бы прямой на ту же дату, а категория «без пересадок» пустела.
const minByDate = (from, to, onlyDepartWindow, directOnly) => {
  const byDate = {};
  for (const o of offers) {
    if (o.from !== from || o.to !== to) continue;
    if (onlyDepartWindow && !o.in_depart) continue;
    if (directOnly && o.transfers !== 0) continue;
    const k = o.date + (o.transfers === 0 ? '|d' : '|c');
    if (!byDate[k] || o.price < byDate[k].price) byDate[k] = o;
  }
  return Object.values(byDate);
};
const arrivalOf = o => {
  const dep = new Date(o.depart_at);
  if (isNaN(dep)) return null;
  const mins = o.duration_min != null ? o.duration_min : ASSUMED_LEG_H * 60;
  return new Date(dep.getTime() + mins * 60000);
};

// --- 2. Связки через хаб ------------------------------------------------------
// Стыковку проверяем по времени вылета и прилёта, а не по датам: иначе получаются
// схемы, где второй рейс улетает раньше, чем приземлился первый.
const combos = [];
for (const hub of HUBS) {
  const legA = minByDate(ORIGIN, hub, true, false);
  if (!legA.length) continue;
  const L = layover(hub);
  for (const dst of VN) {
    const legB = minByDate(hub, dst, false, true);   // во Вьетнам — только прямым
    if (!legB.length) continue;
    for (const a of legA) {
      const arr = arrivalOf(a);
      if (!arr) continue;
      for (const b of legB) {
        const dep = new Date(b.depart_at);
        if (isNaN(dep)) continue;
        const gap = hours(dep - arr);
        if (gap < L.min || gap > L.max) continue;
        const overnight = gap > OVERNIGHT_H;
        combos.push({
          origin: ORIGIN, to: dst, hub, hub_city: name(hub), hub_via: via(hub),
          price: a.price + b.price, date: a.date,
          layover_h: Math.round(gap * 10) / 10,
          overnight, free_stay: overnight && L.freeStay,
          direct: a.transfers === 0,          // второе плечо прямое всегда, значит прямые оба
          short: gap <= SHORT_MAX_H,
          legA: a, legB: b, kind: 'self', src: 'tp',
          airline_code: a.airline_code,
          airline: `${a.airline} + ${b.airline}`,
        });
      }
    }
  }
}
// при равной цене выше тот, у кого стыковка короче — так выбор категории детерминирован
combos.sort((x, y) => (x.price - y.price) || (x.layover_h - y.layover_h));

// Категории по каждому хабу отдельно (сообщение про Астану и сообщение про Алматы):
//   best   — лучшая цена, любая стыковка в пределах хаба
//   direct — лучшая цена, где и Актау -> хаб прямой
//   short  — лучшая цена со стыковкой до SHORT_MAX_H
//   bob    — «всё сошлось»: прямой + короткая и при этом не дороже best больше чем на BOB_TOL
const cats = {};
for (const hub of HUBS) {
  const list = combos.filter(c => c.hub === hub);
  if (!list.length) { cats[hub] = null; continue; }
  const ideal = list.find(c => c.direct && c.short) || null;
  cats[hub] = {
    hub, hub_city: name(hub), hub_via: via(hub), count: list.length,
    best: list[0],
    direct: list.find(c => c.direct) || null,
    short: list.find(c => c.short) || null,
    bob: ideal && ideal.price <= list[0].price + BOB_TOL ? ideal : null,
  };
}

// Самый дешёвый перелёт Актау -> Алматы/Астана в окне. Нужен ветке живого мониторинга:
// tutu обходит «Алматы/Астана -> Вьетнам», и к той цене надо прибавлять первое плечо.
const kz_feed = {};
for (const h of ['ALA', 'NQZ']) {
  const f = cheapest(offers.filter(x => x.from === ORIGIN && x.to === h && x.in_depart));
  if (f) kz_feed[h] = { price: f.price, date: f.date, airline: f.airline };
}

// --- 3. Архив цен -------------------------------------------------------------
// Формат сверен с живым ответом: data — массив записей с value и depart_date,
// return_date пустой = one-way. Приоритет датам окна, иначе выборка шире.
const history = {}, historyWin = {};
const pushHist = (key, price, date) => {
  if (!Number.isFinite(price) || price <= 0) return;
  (history[key] = history[key] || []).push(price);
  if (inDepart(date)) (historyWin[key] = historyWin[key] || []).push(price);
};
try {
  for (const item of $('TP History' + SUF).all()) {
    const r = item.json || {};
    if (r.success === false) continue;
    const data = r.data;
    if (!Array.isArray(data)) continue;
    for (const t of data) {
      if (!t || !t.origin || !t.destination) continue;
      if (t.return_date) continue;
      pushHist(`${norm(t.origin)}-${norm(t.destination)}`,
               Number(t.value != null ? t.value : t.price),
               String(t.depart_date || '').slice(0, 10));
    }
  }
} catch (e) {}

const MIN_SAMPLE = 10;
const stats = {};
for (const key of Object.keys(history)) {
  const win = historyWin[key] || [];
  const useWin = win.length >= MIN_SAMPLE;
  const s = (useWin ? win : history[key]).slice().sort((a, b) => a - b);
  stats[key] = { min: s[0], median: s[Math.floor(s.length / 2)], count: s.length,
                 scope: useWin ? 'наши даты' : 'все даты' };
}

// --- 4. Сводка по направлениям ------------------------------------------------
const routes = {};
for (const dst of VN) {
  const key = `${ORIGIN}-${dst}`;
  const through = offers.filter(o => o.from === ORIGIN && o.to === dst && o.in_depart);
  const self = combos.filter(c => c.to === dst);
  if (!through.length && !self.length) continue;

  const byDate = {};
  for (const o of through) {
    if (!byDate[o.date] || o.price < byDate[o.date].price) byDate[o.date] = o;
  }
  // по одной лучшей связке на хаб: иначе топ забивают три даты одного и того же хаба
  // (self уже отсортирован по цене, так что первая встреченная — самая дешёвая)
  const perHub = {};
  for (const c of self) if (!perHub[c.hub]) perHub[c.hub] = c;
  // лучшая связка на каждую дату вылета из Актау — для доски /dates. Крону она не
  // нужна, а execution data раздувает каждые 5 минут, поэтому только в ветке команды.
  const selfByDate = {};
  if (SUF) for (const c of self) if (!selfByDate[c.date]) selfByDate[c.date] = c;

  routes[key] = {
    origin: ORIGIN, dst, label: `${name(ORIGIN)} → ${name(dst)}`,
    through: { best: cheapest(through), byDate: Object.values(byDate).sort((a, b) => (a.date < b.date ? -1 : 1)), count: through.length },
    self: { best: self[0] || null, top: Object.values(perHub).slice(0, 4), count: self.length,
            byDate: Object.values(selfByDate) },
  };
}

const all = [];
for (const [key, r] of Object.entries(routes)) {
  if (r.through.best) all.push({ ...r.through.best, key, label: r.label, mode: 'through' });
  if (r.self.best) all.push({ ...r.self.best, key, label: r.label, mode: 'self' });
}
all.sort((a, b) => a.price - b.price);

return [{ json: {
  window: WINDOW, legb_max: LEGB_MAX, origin: ORIGIN, hubs: HUBS,
  routes, cats, short_max_h: SHORT_MAX_H, best: all[0] || null, kz_feed, stats,
  count: offers.length, comboCount: combos.length,
} }];

// Ответ на /dates: доска цен по ДАТЕ ВЫЛЕТА ИЗ АКТАУ на всё окно — по строке на дату,
// в каждой лучшая полная цена до Нячанга (две брони через Алматы или Астану, во Вьетнам
// только прямым рейсом). Короткая версия уходит сразу и влезает в одно сообщение; развёрнутая
// (плечи, перевозчики, стыковки) собирается здесь же и кладётся в staticData — её по
// кнопке «📖 Подробнее» отдаёт нода Dates Full, без единого запроса к Travelpayouts.
//   /dates        — все даты окна, 🔥 отмечает цены в пороге
//   /dates 30000  — только варианты не дороже 30 000 ₽
const THRESHOLD = 26000;   // 🔥 тот же порог, что в Prepare — менять в обоих местах

const a = $('Aggregate Cmd').first().json;
const msg = $('On Command').first().json.message || {};
const chat_id = msg.chat.id;
const arg = Number((String(msg.text || '').split(/\s+/)[1] || '').replace(/\D/g, ''));
const limit = Number.isFinite(arg) && arg > 0 ? arg : null;

const MONTHS = ['янв', 'фев', 'мар', 'апр', 'мая', 'июн',
                'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];
const dm = iso => {
  const p = String(iso).split('-');
  return p.length === 3 ? `${Number(p[2])} ${MONTHS[Number(p[1]) - 1]}` : iso;
};
const num = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
const rub = n => num(n) + ' ₽';
const stops = o => o.transfers === 0 ? 'прямой'
  : o.transfers > 0 ? `${o.transfers} пересадк${o.transfers === 1 ? 'а' : 'и'}` : '';
const describe = o => `${rub(o.price)} · ${dm(o.date)} · ${o.airline}` +
  (stops(o) ? ` · ${stops(o)}` : '');
const fire = p => p <= THRESHOLD ? ' 🔥' : '';
const fits = o => o && (limit == null || o.price <= limit);

// date -> [{ city, through, self, best }] в порядке направлений
const board = {};
for (const r of Object.values(a.routes || {})) {
  const city = String(r.label || '').split(' → ')[1] || r.dst;
  const cell = {};
  for (const o of (r.through.byDate || [])) if (fits(o)) (cell[o.date] = cell[o.date] || {}).through = o;
  for (const c of (r.self.byDate || [])) if (fits(c)) (cell[c.date] = cell[c.date] || {}).self = c;
  for (const [date, v] of Object.entries(cell)) {
    const best = v.self && (!v.through || v.self.price < v.through.price) ? v.self : v.through;
    (board[date] = board[date] || []).push({ city, through: v.through || null, self: v.self || null, best });
  }
}
const dates = Object.keys(board).sort();

const scope = limit != null ? `до ${rub(limit)}` : 'все даты';
const head = `📅 Актау → Нячанг по дате вылета · ${dm(a.window.min)} – ${dm(a.window.max)} · ${scope}`;
// время — по Актау (UTC+5)
const now = new Date(Date.now() + 5 * 3600000).toISOString();
const stamp = `${dm(now.slice(0, 10))} ${now.slice(11, 16)} по Актау`;

if (!dates.length) {
  const text = `${head}\n\n` + (limit != null
    ? `Дешевле ${rub(limit)} сейчас ничего нет. Попробуй /dates без суммы — покажу всё окно.`
    : 'Travelpayouts не отдал ни одной цены на окно — попробуй через пару минут.');
  // под пустой доской раскрывать нечего — и прошлую доску под её кнопкой не подсовываем
  $getWorkflowStaticData('global').datesFull = null;
  return [{ json: { chat_id, text, cb: 'dt:0' } }];
}

// ---------- короткая доска ----------
let short = `${head}\n`;
for (const d of dates) {
  short += `\n<b>${dm(d)}</b> — ` + board[d]
    .map(c => `${c.city} ${num(c.best.price)}${c.best.legA ? ' ×2' : ''}${fire(c.best.price)}`)
    .join(' · ');
}
short += `\n\nЦены полные от Актау, ₽, кэш Aviasales на ${stamp}.` +
  `\n×2 — две отдельные брони через хаб · 🔥 — в пороге ${rub(THRESHOLD)}`;

// ---------- развёрнутая версия, режем на сообщения по границам дат ----------
const block = d => {
  let t = `<b>${dm(d)}</b>`;
  for (const c of board[d]) {
    const s = c.self, th = c.through;
    if (c.best === s) {
      t += `\n${c.city} — ${rub(s.price)}${fire(s.price)} · две брони через ${s.hub_via}` +
        `\n  1) ${describe(s.legA)}` +
        `\n  2) ${describe(s.legB)}` +
        `\n  стыковка ${s.layover_h} ч` + (s.free_stay ? ' 🏠' : s.overnight ? ' 🛌' : '');
      if (th) t += `\n  одним билетом: ${describe(th)}`;
    } else {
      t += `\n${c.city} — ${rub(th.price)}${fire(th.price)} · один билет · ${th.airline}` +
        (stops(th) ? ` · ${stops(th)}` : '');
      if (s) t += `\n  двумя бронями через ${s.hub_via}: ${rub(s.price)}, стыковка ${s.layover_h} ч`;
    }
  }
  return t;
};
const tail = `Кэш Aviasales на ${stamp}. 🏠 — ночуем у своих · 🛌 — нужна ночёвка.` +
  `\nДве брони: опоздание на второй рейс никто не компенсирует, стыковку проверь руками.`;
const chunks = [];
let cur = `${head} · подробно`;
for (const d of dates) {
  const b = block(d);
  if (cur.length + b.length + 2 > 3800) { chunks.push(cur); cur = b; }
  else cur += `\n\n${b}`;
}
if (cur.length + tail.length + 2 > 3800) { chunks.push(cur); chunks.push(tail); }
else chunks.push(`${cur}\n\n${tail}`);

const store = $getWorkflowStaticData('global');
const ts = Date.now();
store.datesFull = { ts, chunks };

return [{ json: { chat_id, cb: `dt:${ts}`,
  text: short.length > 3900 ? short.slice(0, 3890) + '…' : short } }];

// Живой поиск tutu под /prices — первое плечо Актау → Алматы/Астана, ровно на те даты,
// что стоят в показанных связках. Вьетнамское плечо тут не спрашиваем: его постоянно
// обходит ветка Live Queries, и /prices показывает накопленную живую доску из staticData.
// Запросов — по числу связок через KZ-хабы в ответе (единицы), и только по команде.
const a = $('Aggregate Cmd').first().json;
const TUTU_GEO = { SCO: 112, ALA: 117, NQZ: 128, NHA: 2161, DAD: 2151 };

const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0;
  return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});
const body = (from, to, date) => JSON.stringify({
  passengers: { child: 0, infant: 0, full: 1 }, serviceClass: 'Y',
  routes: [{ departureCityId: from, arrivalCityId: to, departureDate: date }],
  searchId: uuid(), sessionId: uuid(), pageId: 'n8nflightwatch',
  userData: {}, source: 'offers',
  dynamicFilters: { optionFilters: [], rangeFilters: [], buttonFilters: [], shortcuts: [], switchFilters: [] },
  offset: 0, limit: 100, isNewSearch: true,   // без limit tutu отдаёт только первые 10 предложений
});

const seen = new Set();
const out = [];
for (const r of Object.values(a.routes || {})) {
  for (const c of (r.self.top || [])) {
    if (!TUTU_GEO[c.hub] || !c.legA) continue;
    const key = `${a.origin}-${c.hub}:${c.legA.date}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ json: { key, date: c.legA.date, body: body(TUTU_GEO[a.origin], TUTU_GEO[c.hub], c.legA.date) } });
  }
}
// пустой выход обрубил бы ветку и /prices остался бы без ответа
if (!out.length) out.push({ json: { key: null, date: a.window.min, body: body(112, 117, a.window.min) } });
return out;

// Запросы в AirHint под ответ на /prices: по одному на маршрут, по лучшей найденной цене.
// Максимум 6 запросов и только по команде — на пятиминутном кроне в AirHint не ходим
// вовсе, там запрос уходит лишь вместе с алертом.
// Для связки из двух билетов спрашиваем сквозную пару origin -> dst: предсказывать
// сумму двух отдельных броней сервис не умеет, но вилку «сколько вообще стоит
// туда долететь» даёт.
const a = $('Aggregate Cmd').first().json;
const out = [];

for (const [key, r] of Object.entries(a.routes || {})) {
  const t = r.through.best;
  const s = r.self.best;
  const best = (!t) ? s : (!s ? t : (s.price < t.price ? s : t));
  if (!best) continue;
  out.push({ json: {
    key,
    ah_airline: best.airline_code || 'XX',
    ah_origin: r.origin, ah_dst: r.dst,
    ah_date: best.date, ah_price: Math.round(best.price),
  } });
}

// Пустой выход обрубил бы ветку и /prices остался бы без ответа — поэтому
// всегда отдаём хотя бы один элемент.
if (!out.length) {
  out.push({ json: {
    key: null, ah_airline: 'XX',
    ah_origin: a.origin || 'SCO', ah_dst: 'NHA',
    ah_date: a.window ? a.window.min : '2026-10-15', ah_price: 0,
  } });
}
return out;

// Ответ на /prices: Актау -> Нячанг через Алматы/Астану, во Вьетнам только прямым рейсом.
const a = $('Aggregate Cmd').first().json;
const chat_id = $('On Command').first().json.message.chat.id;

const MONTHS = ['янв', 'фев', 'мар', 'апр', 'мая', 'июн',
                'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];
const dm = iso => {
  const p = String(iso).split('-');
  return p.length === 3 ? `${Number(p[2])} ${MONTHS[Number(p[1]) - 1]}` : iso;
};
const rub = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' ₽';
const stops = o => o.transfers === 0 ? 'прямой'
  : o.transfers > 0 ? `${o.transfers} пересадк${o.transfers === 1 ? 'а' : 'и'}` : '';
const describe = o => `${rub(o.price)} · ${dm(o.date)} · ${o.airline}` +
  (stops(o) ? ` · ${stops(o)}` : '');

// AirHint: сводим запросы и ответы по индексу (одна нода, continueRegularOutput,
// значит на каждый запрос ровно один ответ) и раскладываем по маршрутам.
const ah = {};
try {
  const q = $('AirHint Queries Cmd').all();
  const resp = $('AirHint Cmd').all();
  q.forEach((item, i) => {
    const key = item.json.key;
    const r = resp[i] ? resp[i].json : null;
    if (key && r && !r.error) ah[key] = r;
  });
} catch (e) {}

const ahLine = key => {
  const r = ah[key];
  if (!r) return '';
  const pr = Array.isArray(r.price_range) && r.price_range.length >= 3 ? r.price_range : null;
  if (!r.suggestion && !pr) return '';
  const verdict = r.suggestion === 'Buy' ? 'брать'
    : r.suggestion === 'Wait' ? 'советует подождать' : String(r.suggestion || '');
  let line = `    🔮 AirHint: ${verdict}`;
  // вилка по маршруту, не по дате — проверено 27.08.2026
  if (pr) line += `, по маршруту обычно ${rub(pr[0])} – ${rub(pr[1])} (типично ${rub(pr[2])})`;
  if (r.max_saving) line += `, экономия до ~${r.max_saving}`;
  return line + `\n`;
};

// tutu: живой поиск первого плеча Актау → Алматы/Астана на даты связок.
// Запросы и ответы — по индексу, как у AirHint.
const tutu = {};
try {
  const parse = raw => {
    const arr = typeof raw === 'string' ? JSON.parse(raw) : raw;
    const dd = Array.isArray(arr) ? arr[0] : arr;
    if (!dd || !dd.offers) return null;
    const carriers = {};
    for (const [k, v] of Object.entries(dd.dictionary.common.carriers || {})) carriers[k] = v.name || v.code || k;
    const segs = dd.dictionary.common.segments || {}, routes = dd.dictionary.common.routes || {};
    let best = null;
    for (const o of Object.values((dd.offers || {}).actual || {})) {
      const prices = (o.offerVariants || []).map(v => v.price && v.price.value)
        .filter(p => p && p.amount && p.fraction).map(p => p.amount / p.fraction);
      if (!prices.length) continue;
      const price = Math.min(...prices);
      let carrier = 'н/д', transfers = 0;
      for (const rid of (o.routeIds || [])) {
        const r = routes[rid] || {};
        const ids = r.segmentIds || [rid];
        transfers = Math.max(0, ids.length - 1);
        const s = segs[ids[0]];
        if (s) {
          const car = (s.carriers || []).find(c => c.type === 'marketing') || (s.carriers || [])[0];
          carrier = (car && carriers[car.id]) || s.voyageNumber || 'н/д';
        }
      }
      if (!best || price < best.price) best = { price, carrier, transfers };
    }
    return best;
  };
  const q = $('Tutu Queries Cmd').all();
  const resp = $('Tutu Cmd').all();
  q.forEach((item, i) => {
    const key = item.json.key;
    if (!key || !resp[i]) return;
    const raw = resp[i].json && (resp[i].json.data != null ? resp[i].json.data : resp[i].json);
    const b = parse(raw);
    if (b) tutu[key] = b;
  });
} catch (e) {}

let text = `✈️ Актау → Нячанг, ${dm(a.window.min)} – ${dm(a.window.max)}\n`;
if (a.best) {
  text += `Дешевле всего: ${rub(a.best.price)} — ${a.best.label}` +
          (a.best.mode === 'self' ? ` (двумя билетами через ${a.best.hub_via || a.best.hub_city})` : ' (одним билетом)') + `\n`;
}
text += `\n`;

// сортируем по лучшей доступной цене: сверху то, куда реально дешевле
const best = r => Math.min(
  r.through.best ? r.through.best.price : Infinity,
  r.self.best ? r.self.best.price : Infinity);
const entries = Object.entries(a.routes || {}).sort((x, y) => best(x[1]) - best(y[1]));

for (const [key, r] of entries) {
  text += `${r.label}\n`;
  if (r.through.best) text += `  Одним билетом: ${describe(r.through.best)}\n`;
  const s = (a.stats || {})[key];
  if (r.through.best && s && s.median) {
    text += `    ${Math.round((r.through.best.price / s.median) * 100)} % от цены на типичную дату ` +
            `(медиана по датам ${rub(s.median)}, самая дешёвая ${rub(s.min)}, дат: ${s.count})\n`;
  }
  text += ahLine(key);
  if (r.self.top && r.self.top.length) {
    text += `  Двумя билетами (лучшее через каждый хаб):\n`;
    for (const c of r.self.top) {
      text += `    • ${rub(c.price)} через ${c.hub_via || c.hub_city}: ${describe(c.legA)} + ${describe(c.legB)}, ` +
              `стыковка ${c.layover_h} ч${c.free_stay ? ' 🏠' : c.overnight ? ' 🛌' : ''}\n`;
      const tt = tutu[`${a.origin}-${c.hub}:${c.legA.date}`];
      if (tt) {
        // живой поиск, а не кэш: если он дешевле — первое плечо брать по нему
        text += `      🔎 tutu сейчас, 1-е плечо: ${rub(tt.price)} · ${tt.carrier}` +
                (tt.transfers ? ` · пересадок ${tt.transfers}` : ' · прямой') + `\n`;
      }
    }
  }
  text += `\n`;
}

// Живая доска: то, что накопил постоянный обход tutu. Запросов не делаем — читаем staticData.
const store = $getWorkflowStaticData('global');
const live = store.live || {};
const byRoute = {};
for (const [slot, v] of Object.entries(live)) {
  if (!v || v.price == null || !Number.isFinite(Number(v.price))) continue;
  const [key, date] = slot.split(':');
  if (date < a.window.min || date > a.window.max) continue;
  (byRoute[key] = byRoute[key] || []).push({ date, ...v });
}
if (Object.keys(byRoute).length) {
  text += `🔴 Живые цены (обход tutu, не кэш; ALA-/NQZ- — без плеча из Актау)\n`;
  for (const [key, rows] of Object.entries(byRoute)) {
    rows.sort((x, y) => x.price - y.price);
    const top = rows.slice(0, 3)
      .map(r => `${dm(r.date)} ${rub(r.price)}${r.carrier ? ` (${r.carrier})` : ''}`).join(' · ');
    text += `  ${key}: ${top}   [дат в базе: ${rows.length}]\n`;
  }
  const f = store.kzFeed || {};
  const feed = ['ALA', 'NQZ'].filter(h => f[h]).map(h => `${h} от ${rub(f[h].price)} (${dm(f[h].date)})`);
  if (feed.length) text += `  + Актау → ${feed.join(', ')} — кэш Aviasales\n`;
  text += `\n`;
}

text += `Связок посчитано: ${a.comboCount}, офферов всего: ${a.count}.\n` +
        `Хабы: ${(a.hubs || []).join(', ')}, во Вьетнам — только прямым рейсом. Стыковка от 3 ч: в Астане до 48 ч, ` +
        `в Алматы до 72 ч (🏠 — ночуем у своих). 🛌 = ночёвка за свои.\n` +
        `Все цены — полные от Актау.\n` +
        `⚠️ «Двумя билетами» — две отдельные брони, стыковка на твой риск.\n` +
        `Цены рейсов — из кэша Aviasales (до 48 ч давности), он умеет протухать на сутки; ` +
        `строки 🔎 и 🔴 — живой поиск tutu на сейчас. У tutu агентская наценка: ` +
        `у самого перевозчика (VietJet — в евро) обычно дешевле.`;

// Telegram режет сообщения длиннее 4096 символов (ловили 400 «message is too long»
// 27.08.2026 — шесть маршрутов со связками в один пост не влезают). Бьём по строкам,
// нода Telegram Reply отправит по сообщению на каждый элемент.
const LIMIT = 3900;
const chunks = [];
let buf = '';
for (const line of text.split('\n')) {
  // одна строка длиннее лимита — режем жёстко, иначе она не отправится никогда
  let l = line;
  while (l.length > LIMIT) {
    if (buf) { chunks.push(buf); buf = ''; }
    chunks.push(l.slice(0, LIMIT));
    l = l.slice(LIMIT);
  }
  if (buf.length + l.length + 1 > LIMIT) { chunks.push(buf); buf = l; }
  else { buf = buf ? buf + '\n' + l : l; }
}
if (buf) chunks.push(buf);

return chunks.map((part, i) => ({ json: {
  chat_id,
  text: chunks.length > 1 ? `${part}\n\n— часть ${i + 1} из ${chunks.length} —` : part,
} }));

// ===== Кнопка «🔄 Проверить цену» под алертом =====
// Разбирает callback_data кнопки и раскладывает её на плечи — по элементу на плечо.
// Формат (его собирают Prepare и Live Check, лимит Telegram — 64 байта):
//   rc:<FROM>-<TO>-<ГГММДД>[:<FROM>-<TO>-<ГГММДД>]:<цена из алерта>
// Проверяем РОВНО те плечи и даты, что были в алерте, а не ищем лучший вариант заново:
// смысл кнопки — «тот билет ещё жив и сколько он стоит сейчас», для обзора есть /prices.
const upd = $('On Command').first().json;
const cq = upd.callback_query || {};
const parts = String(cq.data || '').split(':').slice(1);

const legs = [];
let alert_price = null;
for (const p of parts) {
  const m = /^([A-Z]{3})-([A-Z]{3})-(\d{2})(\d{2})(\d{2})$/.exec(p);
  if (m) legs.push({ origin: m[1], destination: m[2], date: `20${m[3]}-${m[4]}-${m[5]}` });
  else if (/^\d+$/.test(p)) alert_price = Number(p);
}

const msg = cq.message || {};
return legs.map((l, i) => ({ json: {
  ...l, leg: i, alert_price, cb: cq.data,
  chat_id: String((msg.chat || {}).id || (cq.from || {}).id || ''),
  message_id: msg.message_id || null,
} }));

// Живой поиск tutu по тем же плечам, что ушли в Travelpayouts. geo_id тути — внутренние
// id, не IATA (поле `id` из suggest: avia.tutu.ru/suggest/city/v5/?name=…&direction=to).
const TUTU_GEO = { SCO: 112, ALA: 117, NQZ: 128, NHA: 2161, DAD: 2151, SGN: 458, HAN: 452,
                   TAS: 424, DXB: 230, SHJ: 469, IST: 419, BKK: 138, KUL: 288, URC: 3908 };

const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0;
  return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});
const body = (from, to, date) => JSON.stringify({
  passengers: { child: 0, infant: 0, full: 1 }, serviceClass: 'Y',
  routes: [{ departureCityId: from, arrivalCityId: to, departureDate: date }],
  searchId: uuid(), sessionId: uuid(), pageId: 'n8nflightwatch',
  userData: {}, source: 'offers',
  dynamicFilters: { optionFilters: [], rangeFilters: [], buttonFilters: [], shortcuts: [], switchFilters: [] },
  offset: 0, limit: 100, isNewSearch: true,   // без limit tutu отдаёт только первые 10 предложений
});

const legs = $('Recheck Queries').all().map(i => i.json);
const out = [];
for (const l of legs) {
  if (!TUTU_GEO[l.origin] || !TUTU_GEO[l.destination]) continue;
  out.push({ json: { leg: l.leg, body: body(TUTU_GEO[l.origin], TUTU_GEO[l.destination], l.date) } });
}
// пустой выход обрубил бы ветку и кнопка осталась бы без ответа
if (!out.length) out.push({ json: { leg: null, body: body(112, 117, legs[0].date) } });
return out;

// Ответ на кнопку «🔄 Проверить цену»: сколько сейчас стоят ТЕ ЖЕ плечи на ТЕ ЖЕ даты.
// На каждое плечо два источника: tutu — живой поиск (но с агентской наценкой),
// Travelpayouts — кэш Aviasales (бывает протухшим). Берём самый дешёвый рейс на дату,
// это не обязательно тот же рейс, что был в алерте. Ответы сводим с запросами по индексу.
const AIRLINES = {
  FZ: 'flydubai', EK: 'Emirates', TK: 'Turkish', VF: 'AJet', HY: 'Uzbekistan',
  KC: 'Air Astana', DV: 'SCAT', J2: 'AZAL', VJ: 'VietJet', VN: 'Vietnam Airlines',
  QH: 'Bamboo', CZ: 'China Southern', SU: 'Аэрофлот', U6: 'Уральские', QR: 'Qatar',
  G9: 'Air Arabia', IX: 'Air India Express', AI: 'Air India', GF: 'Gulf Air',
  PC: 'Pegasus', D7: 'AirAsia X', XJ: 'Thai AirAsia X', CA: 'Air China',
  MU: 'China Eastern', XY: 'flynas', KU: 'Kuwait Airways', WY: 'Oman Air',
  '6E': 'IndiGo', OD: 'Batik Air', ZE: 'Eastar Jet', IQ: 'Qazaq Air', TG: 'Thai Airways',
  MH: 'Malaysia Airlines', AK: 'AirAsia', SQ: 'Singapore', BI: 'Royal Brunei',
};
const CITY = {
  SCO: 'Актау', ALA: 'Алматы', NQZ: 'Астана', NHA: 'Нячанг', DAD: 'Дананг',
  SGN: 'Хошимин', HAN: 'Ханой', DXB: 'Дубай', SHJ: 'Шарджа', IST: 'Стамбул',
  TAS: 'Ташкент', BKK: 'Бангкок', KUL: 'Куала-Лумпур', URC: 'Урумчи',
};
const name = c => CITY[c] || c;
// винительный падеж — для фразы «через …», иначе получается «через Астана»
const VIA = { ...CITY, NQZ: 'Астану', SHJ: 'Шарджу' };

const MONTHS = ['янв', 'фев', 'мар', 'апр', 'мая', 'июн',
                'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];
const dm = iso => {
  const p = String(iso).split('-');
  return p.length === 3 ? `${Number(p[2])} ${MONTHS[Number(p[1]) - 1]}` : iso;
};
const rub = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' ₽';
// текст уходит с parse_mode=HTML, а названия перевозчиков и ссылки приходят снаружи
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const stops = n => n === 0 ? ' · прямой' : n > 0 ? ` · пересадок ${n}` : '';
const hhmm = iso => iso ? ` · вылет ${String(iso).slice(11, 16)}` : '';

// самый дешёвый билет Travelpayouts ровно на запрошенную дату
const parseTp = (r, date) => {
  try {
    if (!r || r.success === false) return null;
    const rows = Array.isArray(r.data) ? r.data : [];
    let best = null;
    for (const t of rows) {
      if (String(t.departure_at || '').slice(0, 10) !== date) continue;
      const price = Number(t.price);
      if (!Number.isFinite(price) || price <= 0) continue;
      if (!best || price < best.price) {
        best = { price, carrier: AIRLINES[t.airline] || t.airline || 'н/д',
                 transfers: Number.isFinite(Number(t.transfers)) ? Number(t.transfers) : null,
                 dep: t.departure_at || null, link: t.link || null };
      }
    }
    return best;
  } catch (e) { return null; }
};

const parseTutu = raw => {
  try {
    const arr = typeof raw === 'string' ? JSON.parse(raw) : raw;
    const d = Array.isArray(arr) ? arr[0] : arr;
    if (!d || !d.offers) return null;
    const common = d.dictionary.common;
    const carriers = {};
    for (const [k, v] of Object.entries(common.carriers || {})) carriers[k] = v.name || v.code || k;
    const segs = common.segments || {}, routes = common.routes || {};
    let best = null;
    for (const o of Object.values((d.offers || {}).actual || {})) {
      const prices = (o.offerVariants || [])
        .map(v => v.price && v.price.value)
        .filter(p => p && p.amount && p.fraction)
        .map(p => p.amount / p.fraction);
      if (!prices.length) continue;
      const price = Math.min(...prices);
      const legs = [];
      for (const rid of (o.routeIds || [])) {
        const r = routes[rid] || {};
        for (const sid of (r.segmentIds || [rid])) {
          const s = segs[sid];
          if (!s) continue;
          const car = (s.carriers || []).find(c => c.type === 'marketing') || (s.carriers || [])[0];
          legs.push({ dep: s.departureDateTime || null,
                      carrier: (car && carriers[car.id]) || s.voyageNumber || 'н/д' });
        }
      }
      if (!best || price < best.price) {
        best = { price, transfers: Math.max(0, legs.length - 1),
                 carrier: legs.length ? legs[0].carrier : 'н/д',
                 dep: legs.length ? legs[0].dep : null };
      }
    }
    return best;
  } catch (e) { return null; }
};

const legs = $('Recheck Queries').all().map(i => i.json);
if (!legs.length) return [];
const meta = legs[0];

const tpItems = $('TP Recheck').all();
const tutuAsked = $('Tutu Recheck Queries').all();
const tutuByLeg = {};
$input.all().forEach((item, i) => {
  const q = tutuAsked[i] ? tutuAsked[i].json : null;
  if (!q || q.leg == null) return;
  const raw = item.json && (item.json.data != null ? item.json.data : item.json);
  tutuByLeg[q.leg] = { asked: true, best: parseTutu(raw) };
});

// даты — по времени Актау (UTC+5): после полуночи вчерашний вылет уже не купить
const today = new Date(Date.now() + 5 * 3600000).toISOString().slice(0, 10);

const first = legs[0], last = legs[legs.length - 1];
let title = `${name(first.origin)} → ${name(last.destination)}`;
if (legs.length > 1) title += ` через ${VIA[first.destination] || first.destination}`;

let text = `🔄 Перепроверка: ${title}`;
let total = 0, complete = true, usedCache = false;

legs.forEach((l, i) => {
  const num = legs.length > 1 ? `${i + 1}) ` : '';
  text += `\n\n${num}${name(l.origin)} → ${name(l.destination)} · ${dm(l.date)}`;
  if (l.date < today) { text += '\n   дата уже прошла'; complete = false; return; }

  const tutu = tutuByLeg[l.leg];
  const tp = parseTp(tpItems[i] ? tpItems[i].json : null, l.date);

  if (tutu && tutu.best) {
    const t = tutu.best;
    text += `\n   🔎 tutu сейчас: ${rub(t.price)} · ${esc(t.carrier)}${hhmm(t.dep)}${stops(t.transfers)}`;
  } else if (tutu) {
    text += '\n   🔎 tutu сейчас: на эту дату ничего не нашёл';
  }
  if (tp) {
    text += `\n   💾 кэш Aviasales: ${rub(tp.price)} · ${esc(tp.carrier)}${hhmm(tp.dep)}${stops(tp.transfers)}`;
    if (tp.link) text += ` · <a href="${esc('https://www.aviasales.ru' + tp.link)}">открыть</a>`;
  } else {
    text += '\n   💾 кэш Aviasales: на эту дату пусто';
  }

  const prices = [tutu && tutu.best ? tutu.best.price : null, tp ? tp.price : null].filter(p => p != null);
  if (!prices.length) { complete = false; return; }
  const min = Math.min(...prices);
  if (tp && tp.price === min && !(tutu && tutu.best && tutu.best.price === min)) usedCache = true;
  total += min;
});

text += '\n\n';
if (complete) {
  text += `${legs.length > 1 ? 'Итого сейчас' : 'Сейчас'} от ${rub(total)}`;
  if (meta.alert_price) {
    const diff = Math.round(total - meta.alert_price);
    text += ` — в алерте было ${rub(meta.alert_price)}` +
      (diff > 0 ? ` (▲ дороже на ${rub(diff)})` : diff < 0 ? ` (▼ дешевле на ${rub(-diff)})` : ' (без изменений)');
  }
  if (usedCache) text += '\n⚠️ Минимум взят из кэша Aviasales — он мог устареть, открой ссылку и убедись.';
} else {
  text += 'Полную цену не собрать: по части плеч на эти даты сейчас нет предложений.';
  if (meta.alert_price) text += ` В алерте было ${rub(meta.alert_price)}.`;
}
if (legs.length > 1) {
  text += '\n⚠️ Это самые дешёвые рейсы на эти даты, не обязательно те же, что в алерте — стыковку сверь по времени.';
}

return [{ json: {
  chat_id: meta.chat_id, message_id: meta.message_id, cb: meta.cb,
  text: text.length > 3900 ? text.slice(0, 3890) + '…' : text,
} }];

// Кнопка «📖 Подробнее» под доской /dates: отдаёт развёрнутую версию, которую Format Dates
// собрал и положил в staticData вместе с короткой. Запросов к источникам тут нет —
// поэтому раскрытое сообщение показывает ровно те же цены, что и доска, а не уехавшие.
// Длинный список приходит несколькими сообщениями (лимит Telegram — 4096 символов).
const cq = $('On Command').first().json.callback_query || {};
const msg = cq.message || {};
const chat_id = String((msg.chat || {}).id || (cq.from || {}).id || '');
const asked = Number(String(cq.data || '').split(':')[1]);

const full = $getWorkflowStaticData('global').datesFull;
if (!full || !Array.isArray(full.chunks) || !full.chunks.length) {
  return [{ json: { chat_id, text: 'Подробностей под эту доску уже нет — вызови /dates ещё раз.' } }];
}
// храним только последнюю доску: под старой кнопкой честно говорим, что данные новее
const newer = Number.isFinite(asked) && asked > 0 && asked !== full.ts
  ? 'ℹ️ После этой доски /dates вызывали ещё раз — показываю самую свежую версию.\n\n' : '';
return full.chunks.map((text, i) => ({ json: { chat_id, text: (i === 0 ? newer : '') + text } }));

// Уведомление о падении воркфлоу. Троттлинг на ноду — 30 мин:
// без него лежащий внешний API заваливает чат десятками одинаковых сообщений.
const QUIET_MS = 30 * 60 * 1000;
const e = $json.execution || {};
const err = e.error || {};
const wf = $json.workflow || {};
const node = e.lastNodeExecuted || '?';
const s = $getWorkflowStaticData('global');
if (!s.errAlerts) s.errAlerts = {};
const st = s.errAlerts[node] || { last: 0, suppressed: 0 };
const now = Date.now();
if (now - st.last < QUIET_MS) { st.suppressed += 1; s.errAlerts[node] = st; return []; }
const repeats = st.suppressed;
s.errAlerts[node] = { last: now, suppressed: 0 };
const text =
  `⚠️ FlightWatch VN2 упал\nВоркфлоу: ${wf.name || '?'}\nНода: ${node}\n` +
  `Ошибка: ${err.message || 'без текста'}` +
  (repeats ? `\n(за последние 30 мин ещё ${repeats} таких, они скрыты)` : '') +
  (e.url ? `\n${e.url}` : '');
return [{ json: { chat_id: '648226895', text } }];
